#include "Aevrynd/FootPlacement3D.h"
#include <algorithm>
#include <atomic>
#include <chrono>
#include <cstdio>
#include <cstring>
#include <vector>

namespace {std::atomic<std::uint64_t> allocationCount{};}
void* operator new(std::size_t size){allocationCount.fetch_add(1,std::memory_order_relaxed);if(void* memory=std::malloc(size?size:1))return memory;throw std::bad_alloc();}

using namespace Aevrynd;
namespace {
Skeleton3D Rig(){Skeleton3D s;s.joints.resize(16);auto set=[&](int i,int p,Vec3 t){s.joints[i].parent=p;s.joints[i].bindTransform.translation=t;};set(0,-1,{});set(1,0,{0,1,0});set(2,1,{0,.5f,0});set(3,2,{0,.4f,0});set(4,1,{-.2f,-.35f,0});set(5,4,{0,-.5f,0});set(6,5,{0,-.45f,0});set(7,1,{.2f,-.35f,0});set(8,7,{0,-.5f,0});set(9,8,{0,-.45f,0});set(10,2,{-.3f,.2f,0});set(11,10,{-.4f,0,0});set(12,11,{-.35f,0,0});set(13,2,{.3f,.2f,0});set(14,13,{.4f,0,0});set(15,14,{.35f,0,0});return s;}
HumanoidSkeletonMap3D Map(){HumanoidSkeletonMap3D m;m.compatibility={0x12345678abcdef01ull};for(std::size_t i=0;i<m.joints.size();++i)m.joints[i]=std::uint16_t(i);return m;}
AnimationPose3D Bind(const Skeleton3D& s,Matrix4 root=Matrix4::Identity()){AnimationPose3D p;p.localTransforms.resize(s.joints.size());p.globalMatrices.resize(s.joints.size());for(std::size_t i=0;i<s.joints.size();++i)p.localTransforms[i]=s.joints[i].bindTransform;BuildAnimationPoseGlobalMatrices3D(s,p,root);return p;}
bool Same(const AnimationPose3D& a,const AnimationPose3D& b){return a.localTransforms.size()==b.localTransforms.size()&&!std::memcmp(a.localTransforms.data(),b.localTransforms.data(),a.localTransforms.size()*sizeof(JointTransform3D))&&!std::memcmp(a.globalMatrices.data(),b.globalMatrices.data(),a.globalMatrices.size()*sizeof(Matrix4));}
int Fail(const char* m){std::fprintf(stderr,"%s\n",m);return 1;}
}
int main(){
    const auto skeleton=Rig();const auto map=Map();if(!skeleton.Valid()||!map.Valid(skeleton,map.compatibility))return Fail("rig invalid");
    FootPlacement3D placement;if(!placement.Configure({})||!placement.Prepare(skeleton,map,map.compatibility))return Fail("prepare failed");
    HeightField3D terrain({{-2,0,-2},5,5,1});terrain.Fill(-.35f);terrain.SetHeight(0,0,-.25f);terrain.SetHeight(4,0,-.05f);terrain.SetHeight(0,4,-.25f);terrain.SetHeight(4,4,-.05f);terrain.RecalculateRange();
    CollisionWorld3D world;for(int i=0;i<128;++i)world.CreateBox({{{50.f+float(i),-1,0},{.4f,.4f,.4f}},1,CollisionLayerAll3D,std::uint64_t(i+1),false});
    FootPlacementFrame3D frame;frame.heightField=&terrain;frame.collisionWorld=&world;frame.cameraDistance=2;
    auto pose=Bind(skeleton);FootPlacementResult3D result{};if(!placement.Evaluate(skeleton,map,frame,pose,&result)||result.lod!=FootPlacementLod3D::Full||result.ikSolves!=2||!result.applied)return Fail("full terrain failed");
    const Vec3 leftUp=Normalize(Vec3{pose.globalMatrices[6][0][1],pose.globalMatrices[6][1][1],pose.globalMatrices[6][2][1]});if(Dot(leftUp,result.left.normalWorld)<.98f)return Fail("normal alignment failed");
    frame.cameraDistance=40;frame.frameIndex=1;auto reduced=Bind(skeleton);if(!placement.Evaluate(skeleton,map,frame,reduced,&result)||result.lod!=FootPlacementLod3D::Reduced||result.ikSolves!=2)return Fail("reduced cadence failed");
    frame.cameraDistance=100;auto disabled=Bind(skeleton);const auto disabledBefore=disabled;if(!placement.Evaluate(skeleton,map,frame,disabled,&result)||result.lod!=FootPlacementLod3D::Disabled||!Same(disabled,disabledBefore))return Fail("disabled failed");
    frame.cameraDistance=2;frame.heightField=nullptr;auto lost=Bind(skeleton);if(!placement.Evaluate(skeleton,map,frame,lost,&result)||result.left.weight!=0)return Fail("disabled stale state reused");
    FootPlacementSettings3D invalidSettings{};invalidSettings.feet[0].soleUpLocal={0,2,0};if(placement.Configure(invalidSettings))return Fail("invalid sole profile accepted");
    // poseRoot 與 modelToWorld 各自非 identity，不可 double-transform；收斂後腳底誤差不超過 2mm。
    FootPlacement3D transformed;if(!transformed.Prepare(skeleton,map,map.compatibility))return Fail("transformed prepare");const Matrix4 root=CreateTransformMatrix({.1f,.2f,0},{0,0,.12f},{1,1,1}),model=CreateTransformMatrix({.5f,0,-.5f},{0,.35f,0},{1,1,1}),worldToModel=CreateRotationMatrix({0,-.35f,0})*CreateTranslationMatrix({-.5f,0,.5f});FootPlacementFrame3D tf;tf.heightField=&terrain;tf.poseRoot=root;tf.modelToWorld=model;tf.worldToModel=worldToModel;AnimationPose3D tp;for(int i=0;i<30;++i){tp=Bind(skeleton,root);if(!transformed.Evaluate(skeleton,map,tf,tp,&result))return Fail("transformed evaluate");}const Vec3 solvedLeft=TransformPoint(model,TransformPoint(tp.globalMatrices[6],{}));if(Length(solvedLeft-result.left.targetWorld)>.002f){std::fprintf(stderr,"transformed error=%f solved=(%f,%f,%f) target=(%f,%f,%f)\n",Length(solvedLeft-result.left.targetWorld),solvedLeft.x,solvedLeft.y,solvedLeft.z,result.left.targetWorld.x,result.left.targetWorld.y,result.left.targetWorld.z);return Fail("transformed foot error exceeded 2mm");}
    // 接觸失聯須多幀單調淡出，不可單幀歸零。
    FootPlacement3D fading;if(!fading.Prepare(skeleton,map,map.compatibility))return Fail("fade prepare");FootPlacementFrame3D ff;ff.heightField=&terrain;auto fp=Bind(skeleton);if(!fading.Evaluate(skeleton,map,ff,fp,&result)||result.left.weight<=0)return Fail("fade contact setup");float previous=result.left.weight;ff.heightField=nullptr;for(int i=0;i<2;++i){fp=Bind(skeleton);if(!fading.Evaluate(skeleton,map,ff,fp,&result)||result.left.weight>=previous||result.left.weight<=0)return Fail("contact loss smoothing failed");previous=result.left.weight;}for(int i=0;i<20&&result.left.weight>0;++i){fp=Bind(skeleton);if(!fading.Evaluate(skeleton,map,ff,fp,&result))return Fail("contact release evaluate");}if(result.left.weight!=0)return Fail("contact release did not finish");
    // 任一腿退化時，pose 與 output 必須整批 rollback。
    auto bad=skeleton;bad.joints[8].bindTransform.translation={};auto badPose=Bind(bad),badBefore=badPose;FootPlacementResult3D sentinel{};sentinel.ikSolves=77;FootPlacement3D badPlacement;if(!badPlacement.Prepare(bad,map,map.compatibility))return Fail("bad prepare");frame.heightField=&terrain;if(badPlacement.Evaluate(bad,map,frame,badPose,&sentinel)||!Same(badPose,badBefore)||sentinel.ikSolves!=77)return Fail("transaction rollback failed");
    // 平台 tuple 在 Reduced 非查詢幀仍映射 raw anchor。
    CollisionWorld3D platformWorld;const auto platform=platformWorld.CreateBox({{{0,-.5f,0},{2,.1f,2}},1,CollisionLayerAll3D,9001,false});FootPlacement3D moving;if(!moving.Prepare(skeleton,map,map.compatibility))return Fail("moving prepare");FootPlacementFrame3D pf;pf.collisionWorld=&platformWorld;pf.cameraDistance=2;MovingPlatformSample3D sample;sample.collider=platform;sample.userData=9001;pf.movingPlatforms={&sample,1};auto pp=Bind(skeleton);if(!moving.Evaluate(skeleton,map,pf,pp,&result)||result.left.source!=FootContactSource3D::Collider)return Fail("platform contact failed");const float oldX=result.left.contactWorld.x;sample.currentLocalToWorld=CreateTranslationMatrix({.25f,0,0});sample.currentWorldToLocal=CreateTranslationMatrix({-.25f,0,0});pf.cameraDistance=40;pf.frameIndex=1;pp=Bind(skeleton);if(!moving.Evaluate(skeleton,map,pf,pp,&result)||std::abs(result.left.contactWorld.x-oldX-.25f)>.002f)return Fail("platform mapping failed");const float platformWeight=result.left.weight;if(!platformWorld.Destroy(platform))return Fail("platform destroy failed");pf.movingPlatforms={};pf.frameIndex=2;pp=Bind(skeleton);if(!moving.Evaluate(skeleton,map,pf,pp,&result)||result.left.weight>=platformWeight||result.left.collider)return Fail("lost platform did not release on reduced frame");
    CollisionWorld3D staticWorld;staticWorld.CreateBox({{{0,-.5f,0},{2,.1f,2}},1,CollisionLayerAll3D,7001,false});FootPlacement3D staticPlacement;if(!staticPlacement.Prepare(skeleton,map,map.compatibility))return Fail("static prepare");FootPlacementFrame3D sf;sf.collisionWorld=&staticWorld;auto sp=Bind(skeleton);if(!staticPlacement.Evaluate(skeleton,map,sf,sp,&result)||result.left.source!=FootContactSource3D::Collider)return Fail("static setup");const float staticWeight=result.left.weight;sf.cameraDistance=40;sf.frameIndex=1;sp=Bind(skeleton);if(!staticPlacement.Evaluate(skeleton,map,sf,sp,&result)||result.left.source!=FootContactSource3D::Collider||!result.left.collider||result.left.weight<staticWeight)return Fail("static collider decayed on reduced frame");
    // 非有限 frame 必須保持 pose/output 原子。
    auto atomic=Bind(skeleton),atomicBefore=atomic;auto atomicOut=result;frame.modelToWorld[0][0]=std::numeric_limits<float>::quiet_NaN();if(placement.Evaluate(skeleton,map,frame,atomic,&result)||!Same(atomic,atomicBefore)||std::memcmp(&result,&atomicOut,sizeof result))return Fail("invalid frame atomic failed");
    frame={};frame.heightField=&terrain;atomic=Bind(skeleton);atomicBefore=atomic;atomicOut=result;frame.poseRoot=CreateTranslationMatrix({1,0,0});if(placement.Evaluate(skeleton,map,frame,atomic,&result)||!Same(atomic,atomicBefore)||std::memcmp(&result,&atomicOut,sizeof result))return Fail("pose root mismatch accepted");
    // 完整 warm 路徑效能；vector data pointer 不得改變。
    FootPlacement3D bench;if(!bench.Prepare(skeleton,map,map.compatibility))return Fail("bench prepare");frame={};frame.heightField=&terrain;frame.collisionWorld=&world;std::vector<long long> samples;samples.reserve(5000);const auto base=Bind(skeleton);auto bp=base;auto* locals=bp.localTransforms.data();auto* globals=bp.globalMatrices.data();const auto allocationsBefore=allocationCount.load();for(int i=0;i<5000;++i){std::copy(base.localTransforms.begin(),base.localTransforms.end(),bp.localTransforms.begin());std::copy(base.globalMatrices.begin(),base.globalMatrices.end(),bp.globalMatrices.begin());const auto begin=std::chrono::steady_clock::now();if(!bench.Evaluate(skeleton,map,frame,bp,nullptr))return Fail("bench evaluate");samples.push_back(std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-begin).count());}const auto allocationsAfter=allocationCount.load();if(allocationsAfter!=allocationsBefore)return Fail("warm allocation detected");if(bp.localTransforms.data()!=locals||bp.globalMatrices.data()!=globals)return Fail("pose storage changed");std::sort(samples.begin(),samples.end());const auto p95=samples[std::size_t(samples.size()*.95)];if(p95>500000)return Fail("p95 exceeded");
    const auto memory=bench.MemoryStats();if(!memory.retainedCapacityBytes||bench.TrimUnusedMemory()!=memory.retainedCapacityBytes||bench.MemoryStats().retainedCapacityBytes)return Fail("trim failed");
    std::printf("FootPlacement3D PASS p95=%lldns\n",p95);return 0;
}
